#!/usr/bin/env python3
"""Generate the browser-loadable application-rules wrapper from canonical JSON."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "data" / "applications" / "application-selection-rules.json"
TARGET = ROOT / "tools" / "rfq-specification-assistant" / "application_rules.js"


def main():
    data = json.loads(SOURCE.read_text(encoding="utf-8"))
    payload = json.dumps(data, ensure_ascii=False, indent=2)
    TARGET.write_text(
        "// Generated by tools/generate_application_rules_js.py; edit the canonical JSON instead.\n"
        "(function (root) {\n"
        "  const data = " + payload + ";\n"
        "  if (typeof module !== \"undefined\" && module.exports) module.exports = data;\n"
        "  root.ApplicationRules = data;\n"
        "})(typeof self !== \"undefined\" ? self : globalThis);\n",
        encoding="utf-8",
    )
    print(f"Generated {TARGET.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
